"""Literal counterexamples and actual feature owners. No human/native claims."""
from pathlib import Path
import subprocess
import unittest
from tests.test_layout_qualification import PRELUDE as LITERAL_GEOMETRY

ROOT = Path(__file__).resolve().parents[1]
PRELUDE = LITERAL_GEOMETRY + r"""
const F=require('./prototype/features/core.js'),TB=require('./prototype/features/text-bounds.js');s.language='en';s.fields.forEach((f,i)=>f.value=[6842,68,72,82][i]);
const healthy=()=>{const o=good();o.text[0].inkHeight=58.5;o.clockProbe=58.5;o.rocket.model='falcon';o.geo={viewportArea:5000,landArea:1000,sourcePoint:[-80,28]};o.occluders=['mission','field-row','count-group'].map(role=>({role,x:0,y:0,w:0,h:0,background:'rgba(0, 0, 0, 0)',display:'block',visibility:'visible',opacity:1}));return o;};
const measured=cs=>cs.map((c,i)=>({id:c.id,trials:32,failures:0,minGap:4,landArea:1000+i}));
"""


class FeatureTest(unittest.TestCase):
    def js(self, code):
        p = subprocess.run(['node', '-e', PRELUDE + code], cwd=ROOT,
                           capture_output=True, text=True, timeout=45)
        self.assertEqual(p.returncode, 0, p.stderr or p.stdout)

    def test_matrix_positive(self):
        self.js("""assert.ok(F.validateAxes());assert.equal(F.axes.length,12);assert.equal(F.featureOne().length,96);assert.equal(new Set(F.featureOne().map(F.signature)).size,96);assert.ok(F.validateCatalog([F.anchor(),...F.featureOne()]));const fs=require('node:fs');const m=require('./prototype/features/font-manifest.json');assert.equal(m.assets.length,4);for(const a of m.assets){assert.ok(fs.existsSync(a.path));assert.match(fs.readFileSync(a.notice,'utf8'),/SIL OPEN FONT LICENSE/);} """)

    def test_matrix_negative(self):
        self.js("""for(const change of [x=>x.axes.pop(),x=>x.axes[0].levels.pop(),x=>x.axes[0].levels[0]=x.axes[0].anchor,x=>x.axes[0].sourceRefs=[],x=>x.axes[0].hypotheses=[]]){const x={axes:structuredClone(F.axes)};change(x);assert.throws(()=>F.validateAxes(x));}const a=F.featureOne();assert.throws(()=>F.validateCatalog([a[0],{...a[0],id:'other'}],[F.anchor()]),/duplicate/);const first={...F.anchor(),id:'order-a',stage:'repair',parents:['ANCHOR'],overrides:{mission:[32,173,288,112],pin:[22,148]}},second={...first,id:'order-b',overrides:{pin:[22,148],mission:[32,173,288,112]}};assert.equal(F.signature(first),F.signature(second));assert.throws(()=>F.validateCatalog([first,second],[F.anchor()]),/duplicate/);const b=structuredClone(a[0]);b.settings.palette='amber';assert.throws(()=>F.validateCatalog([b],[F.anchor()]),/isolated/);const bad=structuredClone(a[0]);bad.tuning={architecture:NaN};assert.throws(()=>F.validateCatalog([bad],[F.anchor()]),/setting/);const injected=structuredClone(a[0]);injected.overrides={pin:[44,255]};assert.throws(()=>F.validateCatalog([injected],[F.anchor()]),/isolated/);""")

    def test_evolution_positive(self):
        self.js("""let pool=[F.anchor(),...F.featureOne()],rs=measured(pool),two=F.featureTwo(pool.slice(1),rs.slice(1));assert.equal(two.length,48);pool.push(...two);rs=measured(pool);const j1=F.joint(1,pool,rs);assert.equal(j1.length,64);pool.push(...j1);const j2=F.joint(2,pool,measured(pool));assert.equal(j2.length,32);pool.push(...j2);const j3=F.joint(3,pool,measured(pool));assert.equal(j3.length,16);assert.equal(new Set([...pool,...j3].map(F.signature)).size,257);assert.ok(F.validateCatalog(j3,pool));const base=pool.find(c=>c.settings.architecture==='earthrise'),rep=[255,261,267,273].map((y,i)=>({...base,id:'R'+i,stage:'repair1',parents:[base.id],overrides:{pin:[44,y]}}));assert.ok(F.validateCatalog(rep,pool));assert.equal(new Set(rep.map(F.signature)).size,4);const ticket=pool.find(c=>c.settings.architecture==='ticket'),repair=[270,276,282,288].map((w,i)=>({...ticket,id:'T'+i,stage:'repair2',parents:[ticket.id],overrides:{operatorWidth:w}}));assert.ok(F.validateCatalog(repair,pool));assert.equal(new Set(repair.map(F.signature)).size,4);""")

    def test_evolution_negative(self):
        self.js("""const a=F.featureOne();assert.throws(()=>F.featureTwo(a,[]),/incomplete/);assert.throws(()=>F.joint(4,a,measured(a)),/stage/);assert.throws(()=>F.joint(1,a,measured(a).slice(1)),/incomplete/);const c=structuredClone(a[0]);c.parents=['unmeasured'];assert.throws(()=>F.validateCatalog([c]),/parent/);assert.throws(()=>F.validateCatalog([a[0]],[a[0]]),/duplicate/);for(const overrides of [{pin:[NaN,2]},{pin:[2]},{unknown:2},{pin:[44,255],unknown:2},{operatorWidth:NaN},{operatorWidth:0},{operatorWidth:391}])assert.throws(()=>F.validateCatalog([{...a[0],id:'broken',overrides}],[F.anchor()]),/override/);""")

    def test_measurement_positive(self):
        self.js("""const d=require('./openspec/changes/expand-feature-research/evidence/atlas-word-bounds-diagnostic.json')[0];const tb=TB.analyze(d.fullText,d.tokens,{x:0,w:d.parentWidth});assert.equal(tb.coverage,true);assert.equal(tb.clipped,false);assert.equal(tb.lines.length,2);assert.ok(d.fullRangeRects.some(r=>r.x+r.w>d.parentWidth+.02));const probe=require('./openspec/changes/expand-feature-research/evidence/atlas-word-bounds-corrected.json')[0];assert.equal(probe.productPurpose.wordBounds.coverage,true);assert.deepEqual(F.evaluate(healthy(),s).failures,[]);const o=healthy();o.text[0].font=76;assert.deepEqual(F.evaluate(o,s).failures,[]);const no=structuredClone(s);no.fixture.point=null;o.pin=null;o.geo={landArea:0,viewportArea:0,sourcePoint:null};assert.deepEqual(F.evaluate(o,no).failures,[]);""")

    def test_measurement_negative(self):
        self.js("""const fs=require('node:fs'),zlib=require('node:zlib'),campaign=JSON.parse(zlib.gunzipSync(fs.readFileSync('openspec/changes/expand-feature-research/evidence/campaign.json.gz'))),reg={records:campaign.currentAudit.records,scenes:campaign.training},actual=reg.records.find(r=>!r.failures.length&&r.observation.text.some(t=>t.wordBounds)),actualScene=reg.scenes.find(s=>s.id===actual.scene),candidate=campaign.generations.flatMap(g=>g.candidates).find(c=>c.id===actual.candidate);assert.deepEqual(F.evaluate(actual.observation,actualScene,candidate).failures,[]);const hidden=campaign.currentAudit.records.find(r=>r.candidate==='R4-07'&&r.failures.includes('marker:background-occluded')),hiddenScene=campaign.training.find(s=>s.id===hidden.scene),hiddenCandidate=campaign.generations.flatMap(g=>g.candidates).find(c=>c.id==='R4-07');assert.ok(hidden);assert.ok(F.evaluate(hidden.observation,hiddenScene,hiddenCandidate).failures.includes('marker:background-occluded'));assert.equal(F.qualify(hiddenCandidate.id,[hiddenScene],[{...hidden,failures:[]}],hiddenCandidate).passed,false);const fg=structuredClone(actual.observation);delete fg.occluders;assert.ok(F.evaluate(fg,actualScene,candidate).failures.includes('foreground-measurement'));for(const mutate of [t=>t.wordBounds.tokens.pop(),t=>t.wordBounds.tokens[0].end--,t=>t.wordBounds.tokens[0].rects[0].w=NaN,t=>t.lines[0].w--,t=>t.clipped=true]){const o=structuredClone(actual.observation),t=o.text.find(t=>t.wordBounds);mutate(t);assert.ok(F.evaluate(o,actualScene,candidate).failures.includes('word-bounds:'+t.role));const raw={...F.evaluate(o,actualScene,candidate),candidate:candidate.id,failures:[],observation:o};assert.equal(F.qualify(candidate.id,[actualScene],[raw],candidate).passed,false);}const d=require('./openspec/changes/expand-feature-research/evidence/atlas-word-bounds-diagnostic.json');assert.equal(TB.analyze(d[1].fullText,d[1].tokens,{x:0,w:d[1].parentWidth}).clipped,true);for(const mutate of [x=>x.pop(),x=>x[0].end--,x=>x[0].text='wrong',x=>x[0].rects=[],x=>x[0].rects[0].w=NaN]){const tokens=structuredClone(d[0].tokens);mutate(tokens);assert.equal(TB.analyze(d[0].fullText,tokens,{x:0,w:240}).coverage,false);}assert.equal(TB.analyze(d[0].fullText,d[0].tokens,{x:0,w:240},true).clipped,true);for(const [change,prefix]of[[o=>delete o.occluders,'foreground-'],[o=>o.occluders[0].w=NaN,'foreground-'],[o=>o.occluders[0]={role:'mission',x:o.pin.x-10,y:o.pin.y-10,w:20,h:20,background:'rgb(5, 10, 17)',display:'block',visibility:'visible',opacity:1},'marker:background-occluded'],[o=>o.clockProbe=54,'clock-probe'],[o=>o.text[0].inkHeight=54.99,'clock-ink'],[o=>o.rocket.model='electron','rocket-identity'],[o=>o.pin.x=NaN,'marker:'],[o=>o.geo.landArea=NaN,'geography-'],[o=>o.geo.sourcePoint=[0,0],'geography-source'],[o=>o.geo.viewportArea=-1,'geography-'],[o=>o.geo.landArea=6000,'geography-'],[o=>o.text[0].value='09:09','semantic:'],[o=>o.text[0].contrast=4.49,'contrast:'],[o=>o.text[0].inkLines=[],'missing-lines:']]){const o=healthy();change(o);assert.ok(F.evaluate(o,s).failures.some(f=>f.startsWith(prefix)),prefix);} """)

    def test_qualification_positive(self):
        self.js("""const o=healthy(),r={...F.evaluate(o,s),candidate:'C',observation:o};assert.deepEqual(F.qualify('C',[s],[r],F.anchor()),{passed:true,errors:[]});const fs=require('node:fs'),zlib=require('node:zlib'),path='openspec/changes/expand-feature-research/evidence/',campaign=JSON.parse(zlib.gunzipSync(fs.readFileSync(path+'campaign.json.gz'))),selection=JSON.parse(fs.readFileSync(path+'final-selection.json')),freeze=JSON.parse(fs.readFileSync(path+'confirm3-freeze.json')),fresh=campaign.controls.find(x=>x.kind==='confirm3'),reg=campaign.controls.find(x=>x.kind==='regression128');assert.ok(fresh,'actual unopened second confirmation required');assert.equal(fresh.scenes.length,24);const crypto=require('node:crypto'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');const correction=JSON.parse(fs.readFileSync(path+'selection-reporting-correction.json')),before=JSON.parse(fs.readFileSync(correction.frozenSnapshotPath));assert.equal(correction.changedField,'candidateIds');assert.deepEqual(selection,{...before,candidateIds:selection.candidateIds});assert.deepEqual(selection.candidateIds,selection.candidates.map(c=>c.id));assert.deepEqual(selection.candidateIds.slice().sort(),Object.keys(selection.names).sort());for(const [file,sha]of Object.entries(freeze.sourceSha256)){if(file===path+'final-selection.json'){assert.equal(hash(correction.frozenSnapshotPath),sha);assert.equal(hash(file),correction.currentSha256);}else assert.equal(hash(file),sha,'Frozen source drift '+file);}const input=JSON.parse(fs.readFileSync(path+'confirm3_24/inputs.json')),seal=JSON.parse(fs.readFileSync(path+'confirm3_24/SEAL.json'));assert.deepEqual(fresh.scenes,input.scenes);for(const [file,entry]of Object.entries(seal.files))assert.equal(hash(path+'confirm3_24/'+file),entry.sha256,'Releasedpacket drift '+file);const release=JSON.parse(fs.readFileSync(path+'confirm3-release.json'));assert.equal(hash(path+'confirm3-freeze.json'),release.freezeSha256);assert.equal(hash(path+'confirm3_24/SEAL.json'),release.packetSealSha256);assert.deepEqual(fresh.candidateIds,freeze.candidateIds);assert.deepEqual(campaign.topFive,freeze.candidateIds);assert.equal(campaign.generations.flatMap(g=>g.candidates).length,280);assert.equal(campaign.currentAudit.records.length,8960);assert.equal(fresh.records.length,120);for(const candidate of selection.candidates){assert.equal(F.signature(candidate),F.signature(freeze.candidates.find(c=>c.id===candidate.id)));for(const set of [reg,fresh])assert.equal(F.qualify(candidate.id,set.scenes,set.records.filter(r=>r.candidate===candidate.id),candidate).passed,true);}assert.equal(new Set(selection.candidates.map(c=>c.settings.architecture)).size,5);const shared=campaign.training[0].id,obs=id=>campaign.currentAudit.records.find(r=>r.candidate===id&&r.scene===shared).observation,role=(o,r)=>o.text.find(t=>t.role===r);const base=obs('R4-01'),ticket=obs('R4-03'),relay=obs('R4-05');assert.ok(role(base,'time').y<60);assert.ok(role(ticket,'time').y>=180&&role(ticket,'rocket').y<50&&role(ticket,'purpose').y<role(ticket,'time').y);assert.ok(role(relay,'time').y>=100&&role(relay,'time').y<140&&role(relay,'rocket').y<50&&role(relay,'purpose').y>role(relay,'time').y);assert.ok(campaign.controls.find(c=>c.kind==='reconfirm').results.some(r=>r.failures>0));assert.ok(campaign.controls.find(c=>c.kind==='stress').results.some(r=>r.failures>0));const known=new Set(reg.scenes.map(s=>s.id));assert.ok(fresh.scenes.every(s=>!known.has(s.id)));assert.ok(campaign.controls.find(c=>c.kind==='confirm').results.some(r=>r.failures>0),'retain actual original failure');""")

    def test_qualification_negative(self):
        self.js("""const r={...F.evaluate(healthy(),s),candidate:'C',observation:healthy()};for(const change of [x=>x.scene='unrelated',x=>x.candidate='wrong',x=>x.observation.text[0].value='19:19',x=>x.landArea=99,x=>x.failures=['hidden'],x=>delete x.observation]){const a=structuredClone(r);change(a);assert.equal(F.qualify('C',[s],[a],F.anchor()).passed,false);}assert.equal(F.qualify('C',[s],[],F.anchor()).passed,false);""")

    def test_boundaries_positive(self):
        self.js("""assert.deepEqual(F.outside(s),[]);const x=structuredClone(s);x.fields[0].role='battery';assert.ok(F.outside(x).includes('field-roles'));const o=healthy();x.fixture.operator.displayLabel='A'.repeat(40);o.text.find(t=>t.role==='operator').value='A'.repeat(40);assert.ok(F.evaluate(o,x).outsideBenchmark.includes('operator'));const pixels=new Uint8ClampedArray(16);assert.equal(F.countPixels(pixels,2,2).ratio,0);""")

    def test_boundaries_negative(self):
        self.js("""for(const change of [x=>x.clock='25:99',x=>x.language='zz',x=>x.fixture.point=[0,999],x=>x.countdown.displayLabel='X'.repeat(17),x=>x.fields[0].displayLabel='X'.repeat(8)]){const x=structuredClone(s);change(x);assert.ok(F.outside(x).length);}const x=structuredClone(s);x.fixture.point=null;const o=healthy();o.pin=null;assert.ok(F.evaluate(o,x).failures.includes('invented-geography-area'));const pixels=new Uint8ClampedArray(16);pixels[0]=1;pixels[3]=255;assert.equal(F.countPixels(pixels,2,2).passed,false);""")


if __name__ == '__main__':
    unittest.main()
